package com.mcnex.conversation;
import android.app.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;
public class StyleAnimationProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private boolean contains(View v,String s){if(v instanceof TextView&&((TextView)v).getText().toString().equals(s))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(contains(g.getChildAt(i),s))return true;}return false;}
 public void onStart(){JSONObject report=new JSONObject();try{MainActivity a=(MainActivity)startActivitySync(new android.content.Intent(getTargetContext(),MainActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));for(int tab:new int[]{1,2,0}){runOnMainSync(()->a.navigate(tab));Thread.sleep(450);runOnMainSync(()->{ViewGroup content=a.findViewById(android.R.id.content);if(content.getChildCount()!=1||Math.abs(content.getChildAt(0).getTranslationX())>.1)throw new IllegalStateException("Transition cleanup failed");if(!contains(content,new String[]{"대화는 이어지고,\n기록은 남습니다.","휴대폰 회의","회의록 설정"}[tab]))throw new IllegalStateException("Target page missing");});}runOnMainSync(()->{long t=SystemClock.uptimeMillis();a.dispatchTouchEvent(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,900,260,0));a.dispatchTouchEvent(MotionEvent.obtain(t,t+60,MotionEvent.ACTION_MOVE,100,260,0));a.dispatchTouchEvent(MotionEvent.obtain(t,t+120,MotionEvent.ACTION_UP,100,260,0));});Thread.sleep(450);runOnMainSync(()->{if(!contains(a.findViewById(android.R.id.content),"휴대폰 회의"))throw new IllegalStateException("Swipe target missing");});report.put("tabAnimations",true).put("swipeAnimation",true).put("overlayCleanup",true).put("ok",true);Thread.sleep(1500);}catch(Throwable e){try{report.put("ok",false).put("error",e.toString());}catch(Exception ignored){}}try(java.io.FileOutputStream f=getTargetContext().openFileOutput("style-animation-probe.json",0)){f.write(report.toString().getBytes("UTF-8"));}catch(Exception ignored){}Bundle b=new Bundle();b.putString("report",report.toString());finish(report.optBoolean("ok")?-1:0,b);}
}
